import itertools, os, warnings
from collections import defaultdict
from typing import Dict, List, Optional, Sequence, Tuple, Union

import anndata as ad
import numpy as np
import pandas as pd
from joblib import Parallel, delayed
from scipy.sparse import issparse
from scipy.stats import chi2
from statsmodels.stats.multitest import multipletests

# -----------------------------------------------------------------------------
# Optional Numba helpers - falls back gracefully if missing
# -----------------------------------------------------------------------------
try:
    from numba import njit, prange  # type: ignore
    _NUMBA = True
except ModuleNotFoundError:  # pragma: no cover
    _NUMBA = False
    def njit(*_a, **_kw):
        def _decor(f): return f
        return _decor
    prange = range  # type: ignore

# -----------------------------------------------------------------------------
# Utility helpers
# -----------------------------------------------------------------------------
SEP = "|"  # separator for composite labels (unlikely to be in raw IDs)


def _safe_sum(x):
    """Axis-0 sum that works for dense and sparse matrices (returns 1-D)."""
    return np.asarray(x.sum(axis=0)).ravel()


def _make_group_key(df: pd.DataFrame, cols: Sequence[str]):
    """Composite key col0|col1|... Works whether cols is a list or tuple."""
    if isinstance(cols, tuple):
        cols = list(cols)
    if len(cols) == 1:
        return df[cols[0]].astype(str)
    return df[cols].astype(str).agg(SEP.join, axis=1)


@njit(cache=True)
def _chi2_stat(a: np.ndarray, b: np.ndarray):
    n1, n2 = a.sum(), b.sum()
    tot = n1 + n2
    exp1 = (a + b) * (n1 / tot)
    exp2 = (a + b) * (n2 / tot)
    stat = ((a - exp1) ** 2 / exp1).sum() + ((b - exp2) ** 2 / exp2).sum()
    return stat, a.size - 1


def _min_expected_count(a: np.ndarray, b: np.ndarray) -> float:
    """
    Minimum expected count in a 2xK contingency table (a,b are length K).
    Used as a chi2 validity guard (classic rule of thumb: >= 5).
    """
    n1 = float(a.sum()); n2 = float(b.sum()); tot = n1 + n2
    col = a + b
    exp1 = col * (n1 / tot)
    exp2 = col * (n2 / tot)
    return float(np.minimum(exp1.min(), exp2.min()))


def _fisher_exact_mc(
    a: np.ndarray,
    b: np.ndarray,
    n_sim: int = 2000,
    rng: np.random.Generator = None,
) -> Tuple[float, float]:
    """
    Monte Carlo Fisher's exact test for a 2xK contingency table.
    Returns (observed_chi2_stat, simulated_p_value).
    """
    if rng is None:
        rng = np.random.default_rng(0)
    a = a.astype(np.float64)
    b = b.astype(np.float64)
    obs_stat, _ = _chi2_stat(a, b)
    col_totals = (a + b).astype(int)
    n1 = int(a.sum())
    K = len(a)
    count_ge = 0
    for _ in range(n_sim):
        sim_a = np.empty(K, dtype=np.float64)
        remaining_n1 = n1
        remaining_col = col_totals.copy()
        remaining_total = int(remaining_col.sum())
        for j in range(K - 1):
            if remaining_total <= 0:
                sim_a[j] = 0.0
            else:
                draw = int(rng.hypergeometric(
                    remaining_col[j],
                    max(0, remaining_total - remaining_col[j]),
                    min(remaining_n1, remaining_total),
                ))
                sim_a[j] = float(draw)
                remaining_n1 -= draw
                remaining_total -= remaining_col[j]
                remaining_col[j] = 0
        sim_a[K - 1] = float(remaining_n1)
        sim_b = col_totals.astype(np.float64) - sim_a
        sim_stat, _ = _chi2_stat(sim_a, sim_b)
        if sim_stat >= obs_stat:
            count_ge += 1
    p_val = (count_ge + 1) / (n_sim + 1)
    return float(obs_stat), float(p_val)


def _cramers_v(chi2_stat: float, n: float) -> float:
    """Cramer's V for a 2xK table (min(r,c)-1 = 1). Matches Hypatia R."""
    return float(np.sqrt(chi2_stat / n))


def _delta_pi_from_counts(
    ac: np.ndarray,
    bc: np.ndarray,
    signed: bool = True,
) -> Tuple[float, int]:
    """
    Compute Tilgner delta-pi directly from pseudobulk isoform count vectors.
    Returns (delta_pi_value, index_of_max_abs_delta_transcript).
    """
    props_a = ac / ac.sum()
    props_b = bc / bc.sum()
    deltas = props_a - props_b

    pos = deltas[deltas > 0]
    neg = deltas[deltas < 0]
    pos_sorted = np.sort(np.abs(pos))[::-1]
    neg_sorted = np.sort(np.abs(neg))[::-1]

    if pos_sorted.sum() >= neg_sorted.sum():
        val = float(pos_sorted[:2].sum())
    else:
        val = float(neg_sorted[:2].sum())
        if signed:
            val = -val

    max_idx = int(np.argmax(np.abs(deltas)))
    return val, max_idx


# -----------------------------------------------------------------------------
# Per-cell delta-pi helpers (used when psi_mode="cell")
# -----------------------------------------------------------------------------
def delta_pi_one_gene(dpsi: pd.Series) -> float:
    """Unsigned Tilgner delta-pi (always >= 0)."""
    pos = dpsi[dpsi > 0].abs().sort_values(ascending=False)
    neg = dpsi[dpsi < 0].abs().sort_values(ascending=False)
    if pos.sum() >= neg.sum():
        return float(pos.head(2).sum())
    return float(neg.head(2).sum())


def delta_pi_one_gene_signed(dpsi: pd.Series) -> float:
    """Signed Tilgner delta-pi (keeps +/- sign of the stronger direction)."""
    pos = dpsi[dpsi > 0].abs().sort_values(ascending=False)
    neg = dpsi[dpsi < 0].abs().sort_values(ascending=False)
    if pos.sum() >= neg.sum():
        return float(+pos.head(2).sum())
    return float(-neg.head(2).sum())


# -----------------------------------------------------------------------------
# Transcript-level metric builder
# -----------------------------------------------------------------------------
def build_isoform_metrics_table(
    adata: ad.AnnData,
    group_columns: Sequence[str] | str,
    *,
    comparisons: Sequence[Tuple[str, str]] | None = None,
    group_vs_rest: bool = False,
    epsilon: float = 1e-6,
    n_jobs: int = -1,
) -> pd.DataFrame:
    if isinstance(group_columns, str):
        group_columns = [group_columns]
    adx = adata.copy()
    adx.obs["_grp"] = _make_group_key(adx.obs, group_columns)
    grp_col = "_grp"

    tx_ids = adx.var.index.values
    gene_ids = adx.var.get("geneId", adx.var.index)

    gene2tx: Dict[str, np.ndarray] = defaultdict(list)
    for idx, gid in enumerate(gene_ids):
        gene2tx[gid].append(idx)
    gene2tx = {g: np.asarray(v, dtype=int) for g, v in gene2tx.items()}

    groups = sorted(adx.obs[grp_col].unique())

    tasks: List[Tuple[np.ndarray, np.ndarray, str, str]] = []
    if group_vs_rest:
        for g in groups:
            m1 = adx.obs[grp_col] == g
            m2 = ~m1
            tasks.append((m1.values, m2.values, str(g), "rest"))
    else:
        for g1, g2 in (comparisons or itertools.combinations(groups, 2)):
            m1 = adx.obs[grp_col] == g1
            m2 = adx.obs[grp_col] == g2
            tasks.append((m1.values, m2.values, str(g1), str(g2)))

    def _worker(mask1, mask2, lab1, lab2):
        A1, A2 = adx[mask1], adx[mask2]
        X1, X2 = A1.X, A2.X
        n1, n2 = A1.n_obs, A2.n_obs

        c1, c2 = _safe_sum(X1), _safe_sum(X2)
        mexpr1, mexpr2 = c1 / n1, c2 / n2

        if issparse(X1):
            p1 = np.asarray((X1 > 0).mean(axis=0)).ravel() * 100
            p2 = np.asarray((X2 > 0).mean(axis=0)).ravel() * 100
        else:
            p1 = (X1 > 0).sum(axis=0).ravel() / n1 * 100
            p2 = (X2 > 0).sum(axis=0).ravel() / n2 * 100

        psi1_all = np.empty(tx_ids.size, dtype=np.float32)
        dpsi = np.empty_like(psi1_all)
        lfc = np.empty_like(psi1_all)

        for idxs in gene2tx.values():
            M1, M2 = X1[:, idxs], X2[:, idxs]
            rs1 = np.asarray(M1.sum(axis=1)).ravel() + epsilon
            rs2 = np.asarray(M2.sum(axis=1)).ravel() + epsilon
            if issparse(M1):
                psi1 = np.asarray(M1.multiply(1 / rs1[:, None]).sum(axis=0)).ravel() / n1
                psi2 = np.asarray(M2.multiply(1 / rs2[:, None]).sum(axis=0)).ravel() / n2
            else:
                psi1 = (M1 * (1 / rs1)[:, None]).sum(axis=0) / n1
                psi2 = (M2 * (1 / rs2)[:, None]).sum(axis=0) / n2
            psi1_all[idxs] = psi1
            dpsi[idxs] = psi1 - psi2

        lfc[:] = np.log((psi1_all + epsilon) / ((psi1_all - dpsi) + epsilon))

        return pd.DataFrame({
            "comparison": f"{lab1}__{lab2}",
            "gene_id": gene_ids,
            "transcript_id": tx_ids,
            "group_1": lab1,
            "group_2": lab2,
            "count_group1": c1,
            "count_group2": c2,
            "mean_expr_group1": mexpr1,
            "mean_expr_group2": mexpr2,
            "percent_expr_group1": p1,
            "percent_expr_group2": p2,
            "avg_psi_group1": psi1_all,
            "log_fc": lfc,
            "delta_psi": dpsi,
            "n_cells_group1": n1,
            "n_cells_group2": n2,
            "total_cells": n1 + n2,
            "total_count": c1 + c2,
        })

    dfs = Parallel(n_jobs=n_jobs)(delayed(_worker)(*t) for t in tasks)
    return pd.concat(dfs, ignore_index=True) if dfs else pd.DataFrame()


# -----------------------------------------------------------------------------
# SwitchSearch
# -----------------------------------------------------------------------------
class SwitchSearch(ad.AnnData):
    """
    chi2/Fisher isoform-switch screen supporting nested and 1-vs-rest designs.

    FP-control additions:
      - min_expected_count: chi2 validity guard (default 5.0; set None to disable)
      - min_gene_total: require gene total counts per group (default None/off)
      - min_isoforms_gene: require >= this many isoforms for a gene (default 2)
      - min_present_isoforms: require >= this many isoforms pass count threshold (optional)
      - min_prevalence_pct: require >= this % of cells express an isoform (optional)
      - min_prevalent_isoforms: require >= N isoforms meet prevalence criterion (default 2)
      - prevalence_count_thr: isoform considered expressed if count >= thr (default 1)
    """
    def __init__(
        self,
        anndata_obj: ad.AnnData,
        *,
        group_columns: Sequence[str] | str = ("cell_type",),
        n_jobs: int = -1,
        fast_mode: bool = True,
        precompute_metrics: bool = False,
    ):
        super().__init__(anndata_obj.copy())
        self._metric_signature: Optional[Tuple[Tuple[str, ...], bool]] = None
        self.n_jobs = os.cpu_count() if n_jobs in (-1, 0) else n_jobs
        if isinstance(group_columns, str):
            group_columns = [group_columns]
        self.group_columns = tuple(group_columns)
        self.fast_mode = fast_mode
        self.obs["_grp"] = _make_group_key(self.obs, self.group_columns)
        self.transcript_metrics: Optional[pd.DataFrame] = None
        if precompute_metrics and not fast_mode:
            self._build_metrics(group_vs_rest=False)

    def _build_metrics(self, *, group_vs_rest: bool):
        self.transcript_metrics = build_isoform_metrics_table(
            self,
            self.group_columns,
            group_vs_rest=group_vs_rest,
            n_jobs=self.n_jobs,
        )
        self._metric_signature = (self.group_columns, group_vs_rest)

    def _ensure_metrics(self, df: pd.DataFrame, *, group_vs_rest: bool, n_jobs: int):
        sig = (self.group_columns, group_vs_rest)
        if self._metric_signature != sig:
            self.transcript_metrics = None
            self._metric_signature = None

        if self.transcript_metrics is None:
            ad_sub = self[:, self.var["geneId"].isin(df["gene_id"].unique())]
            self.transcript_metrics = build_isoform_metrics_table(
                ad_sub,
                self.group_columns,
                group_vs_rest=group_vs_rest,
                n_jobs=n_jobs,
            )
            self._metric_signature = sig
            return

        key = ["gene_id", "group_1", "group_2"]
        need = pd.merge(
            df[key].drop_duplicates(),
            self.transcript_metrics[key].drop_duplicates(),
            on=key, how="left", indicator=True
        ).query("_merge == 'left_only'").drop(columns="_merge")
        if need.empty:
            return

        genes = need["gene_id"].unique()
        ad_sub = self[:, self.var["geneId"].isin(genes)]
        extra = build_isoform_metrics_table(
            ad_sub,
            self.group_columns,
            group_vs_rest=group_vs_rest,
            n_jobs=n_jobs,
        )
        self.transcript_metrics = (
            pd.concat([self.transcript_metrics, extra], ignore_index=True)
              .drop_duplicates(subset=["gene_id", "transcript_id", "group_1", "group_2"])
        )
        self._metric_signature = sig

    # ------------------------------------------------------------------
    # Permutation-based FP sanity check
    # ------------------------------------------------------------------
    def permutation_fp_check(
        self,
        *,
        primary_col: str,
        n_perm: int = 20,
        seed: int = 0,
        min_reads: int = 30,
        fdr: float = 0.05,
        eff_thr: float = 0.10,
        group_vs_rest: bool = False,
        within: str = "primary",
        n_jobs: Optional[int] = None,
        method: str = "auto",
        n_sim: int = 2000,
        min_prevalence_pct: Optional[float] = None,
        min_prevalent_isoforms: int = 2,
        prevalence_count_thr: int = 1,
    ) -> pd.Series:
        rng = np.random.default_rng(seed)
        counts = []
        for perm_idx in range(n_perm):
            adp = self.copy()
            adp.obs = adp.obs.copy()
            adp.obs[primary_col] = rng.permutation(adp.obs[primary_col].values)

            ss_p = SwitchSearch(adp, group_columns=list(self.group_columns), fast_mode=True)
            res = ss_p.find_switches_chi2(
                primary_col=primary_col,
                within=within,
                group_vs_rest=group_vs_rest,
                method=method,
                n_sim=n_sim,
                seed=seed + perm_idx,
                min_reads=min_reads,
                fdr=fdr,
                n_jobs=n_jobs,
                min_prevalence_pct=min_prevalence_pct,
                min_prevalent_isoforms=min_prevalent_isoforms,
                prevalence_count_thr=prevalence_count_thr,
            )

            if res is None or res.empty:
                counts.append(0)
                continue

            res_g = res[(res["adj_pval"] <= fdr) & (res["delta_pi"].abs() >= eff_thr)]
            counts.append(int(res_g["gene_id"].nunique()))

        return pd.Series(counts, name="n_genes_perm")

    # ------------------------------------------------------------------
    # chi2/Fisher screen with FP controls + prevalence gate
    # ------------------------------------------------------------------
    def find_switches_chi2(
        self,
        *,
        primary_col: Optional[str] = None,
        secondary_col: Optional[str] = None,
        within: str = "primary",
        group_vs_rest: bool = False,
        targets: Optional[Sequence[str]] = None,
        # test selection
        method: str = "auto",           # "chi2", "fisher", or "auto"
        n_sim: int = 2000,              # Monte Carlo replicates (fisher only)
        seed: int = 0,                  # RNG seed (fisher only)
        psi_mode: str = "pseudobulk",   # "pseudobulk" or "cell"
        # filtering thresholds
        min_reads: int = 30,
        fdr: float = 0.05,
        min_expected_count: Optional[float] = 5.0,
        min_gene_total: Optional[int] = None,
        min_isoforms_gene: int = 2,
        min_present_isoforms: Optional[int] = None,
        present_count_thr: int = 1,
        min_prevalence_pct: Optional[float] = None,
        min_prevalent_isoforms: int = 2,
        prevalence_count_thr: int = 1,
        # output options
        return_transcript_metrics: bool = False,
        drop_unmatched_metrics: bool = True,
        n_jobs: Optional[int] = None,
        # deprecated -- kept as silent no-ops for backward compat
        calc_effect_size: bool = False,
        effect_size_mode: str = "signed",
    ) -> pd.DataFrame:
        n_jobs = n_jobs or self.n_jobs
        if method not in {"chi2", "fisher", "auto"}:
            raise ValueError("method must be 'chi2', 'fisher', or 'auto'.")
        if psi_mode not in {"pseudobulk", "cell"}:
            raise ValueError("psi_mode must be 'pseudobulk' or 'cell'.")

        # -- composite group labels ----------------------------------------
        if secondary_col is None:
            if primary_col is None:
                primary_col = self.group_columns[0]
            group_key = self.obs[primary_col].astype(str)
        else:
            if primary_col is None:
                raise ValueError("`primary_col` must be provided when `secondary_col` is set.")
            group_key = _make_group_key(self.obs, [primary_col, secondary_col])

        uniq = group_key.unique().tolist()
        masks = {k: (group_key == k).values for k in uniq}
        iso_counts = {k: _safe_sum(self.X[m]) for k, m in masks.items()}

        # -- prevalence prep (optional) ------------------------------------
        prev_pct = None
        if min_prevalence_pct is not None:
            prev_pct = {}
            thr = int(prevalence_count_thr)
            for k, m in masks.items():
                Xk = self.X[m]
                n = int(m.sum())
                if n == 0:
                    prev_pct[k] = np.zeros(self.n_vars, dtype=np.float32)
                    continue
                if issparse(Xk):
                    pk = np.asarray((Xk >= thr).mean(axis=0)).ravel() * 100.0
                else:
                    pk = (Xk >= thr).sum(axis=0).ravel() / n * 100.0
                prev_pct[k] = pk.astype(np.float32)

        # -- comparison pairs ----------------------------------------------
        if group_vs_rest:
            if targets is None:
                targets = uniq
            pairs = [(t, "rest") for t in targets if t in uniq]
        else:
            if secondary_col is None:
                pairs = list(itertools.combinations(sorted(uniq), 2))
            else:
                if within == "primary":
                    pairs = []
                    for p in self.obs[primary_col].unique():
                        ks = [k for k in uniq if k.split(SEP)[0] == str(p)]
                        pairs.extend(itertools.combinations(sorted(ks), 2))
                elif within == "secondary":
                    pairs = []
                    for s in self.obs[secondary_col].unique():
                        ks = [k for k in uniq if k.split(SEP)[1] == str(s)]
                        pairs.extend(itertools.combinations(sorted(ks), 2))
                elif within == "all":
                    pairs = list(itertools.combinations(sorted(uniq), 2))
                else:
                    raise ValueError("within must be 'primary', 'secondary', or 'all'.")

        gene_ids_all = self.var["geneId"].values
        tx_ids_all = self.var.index.values

        # -- worker --------------------------------------------------------
        def _worker(k1: str, k2: str, b_counts: Optional[np.ndarray]):
            a = iso_counts[k1]
            b = b_counts if b_counts is not None else iso_counts[k2]

            valid = (a > min_reads) & (b > min_reads)
            if not valid.any():
                return []

            gene_ids = gene_ids_all[valid]
            tx_ids = tx_ids_all[valid]
            a_v = a[valid].astype(np.float64)
            b_v = b[valid].astype(np.float64)

            p1_v = p2_v = None
            if prev_pct is not None:
                p1_v = prev_pct[k1][valid]
                if k2 == "rest":
                    Xrest = self.X[~masks[k1]]
                    nrest = int((~masks[k1]).sum())
                    if nrest <= 0:
                        p2_v = np.zeros_like(p1_v, dtype=np.float32)
                    else:
                        if issparse(Xrest):
                            p2 = np.asarray((Xrest >= int(prevalence_count_thr)).mean(axis=0)).ravel() * 100.0
                        else:
                            p2 = (Xrest >= int(prevalence_count_thr)).sum(axis=0).ravel() / nrest * 100.0
                        p2_v = p2[valid].astype(np.float32)
                else:
                    p2_v = prev_pct[k2][valid]

            rng_worker = np.random.default_rng(seed) if method in {"fisher", "auto"} else None
            _auto_thr = float(min_expected_count) if min_expected_count is not None else 5.0

            out = []
            for g in np.unique(gene_ids):
                idx = np.flatnonzero(gene_ids == g)
                if idx.size < min_isoforms_gene:
                    continue

                ac = a_v[idx]
                bc = b_v[idx]

                if min_gene_total is not None:
                    if (ac.sum() < min_gene_total) or (bc.sum() < min_gene_total):
                        continue

                if min_present_isoforms is not None:
                    present = int(((ac + bc) >= present_count_thr).sum())
                    if present < min_present_isoforms:
                        continue

                # hard filter only when not routing to Fisher for low-count genes
                if min_expected_count is not None and method != "auto":
                    if _min_expected_count(ac, bc) < float(min_expected_count):
                        continue

                if p1_v is not None:
                    p_ok = int(((p1_v[idx] >= float(min_prevalence_pct)) | (p2_v[idx] >= float(min_prevalence_pct))).sum())
                    if p_ok < int(min_prevalent_isoforms):
                        continue

                # -- test --------------------------------------------------
                if method == "chi2":
                    stat, dof = _chi2_stat(ac, bc)
                    pval = float(chi2.sf(stat, dof))
                    test_used = "chi2"
                elif method == "fisher":
                    stat, pval = _fisher_exact_mc(ac, bc, n_sim=n_sim, rng=rng_worker)
                    dof = int(ac.size - 1)
                    test_used = "fisher"
                else:  # method == "auto": chi2 for well-supported tables, Fisher for borderline
                    if _min_expected_count(ac, bc) >= _auto_thr:
                        stat, dof = _chi2_stat(ac, bc)
                        pval = float(chi2.sf(stat, dof))
                        test_used = "chi2"
                    else:
                        stat, pval = _fisher_exact_mc(ac, bc, n_sim=n_sim, rng=rng_worker)
                        dof = int(ac.size - 1)
                        test_used = "fisher"

                row = {
                    "gene_id": g,
                    "group_1": k1,
                    "group_2": k2,
                    "test_used": test_used,
                    "chi2_stat": float(stat),
                    "p_value": pval,
                    "dof": dof,
                    "cramers_v": _cramers_v(float(stat), float(ac.sum() + bc.sum())),
                }

                # -- pseudobulk effect sizes (free when psi_mode="pseudobulk") --
                if psi_mode == "pseudobulk":
                    props_a = ac / ac.sum()
                    props_b = bc / bc.sum()
                    deltas = props_a - props_b
                    max_delta_idx = int(np.argmax(np.abs(deltas)))
                    dpi, _ = _delta_pi_from_counts(ac, bc, signed=True)
                    gene_tx_ids = tx_ids[idx]
                    row["max_delta"] = float(deltas[max_delta_idx])
                    row["max_delta_transcript"] = gene_tx_ids[max_delta_idx]
                    row["delta_pi"] = dpi

                out.append(row)
            return out

        jobs = [
            (k1, k2, _safe_sum(self.X[~masks[k1]])) if k2 == "rest" else (k1, k2, None)
            for k1, k2 in pairs
        ]

        results = Parallel(n_jobs=n_jobs, backend="threading", prefer="threads")(
            delayed(_worker)(k1, k2, c2) for k1, k2, c2 in jobs
        )
        df = pd.DataFrame([r for sub in results for r in sub])
        if df.empty:
            return df

        # -- multiple testing ----------------------------------------------
        df["adj_pval"] = multipletests(df["p_value"], method="fdr_bh")[1]
        df = df[df["adj_pval"] <= fdr].copy()
        if df.empty:
            return df.reset_index(drop=True)

        # -- post-FDR effect sizes (cell mode) -----------------------------
        if psi_mode == "cell":
            self._ensure_metrics(df, group_vs_rest=group_vs_rest, n_jobs=n_jobs)
            tm = self.transcript_metrics

            eff = (
                tm.groupby(["gene_id", "group_1", "group_2"])["delta_psi"]
                  .apply(delta_pi_one_gene_signed)
                  .rename("delta_pi")
                  .reset_index()
            )
            df = df.merge(eff, on=["gene_id", "group_1", "group_2"], how="left")

            def _max_delta_row(grp):
                idx_max = grp["delta_psi"].abs().idxmax()
                return pd.Series({
                    "max_delta": float(grp.loc[idx_max, "delta_psi"]),
                    "max_delta_transcript": grp.loc[idx_max, "transcript_id"],
                })
            max_d = (
                tm[tm["gene_id"].isin(df["gene_id"])]
                  .groupby(["gene_id", "group_1", "group_2"])
                  .apply(_max_delta_row)
                  .reset_index()
            )
            df = df.merge(max_d, on=["gene_id", "group_1", "group_2"], how="left")

        # -- transcript metrics (optional) ---------------------------------
        if return_transcript_metrics:
            if psi_mode == "pseudobulk":
                rows = []
                for _, grow in df[["gene_id", "group_1", "group_2"]].drop_duplicates().iterrows():
                    g = grow["gene_id"]
                    k1, k2 = grow["group_1"], grow["group_2"]
                    tx_mask = gene_ids_all == g
                    tx_sub = tx_ids_all[tx_mask]
                    c1 = iso_counts[k1][tx_mask]
                    if k2 == "rest":
                        c2 = _safe_sum(self.X[~masks[k1]])[tx_mask]
                    else:
                        c2 = iso_counts[k2][tx_mask]
                    t1 = c1.sum(); t2 = c2.sum()
                    p1 = c1 / t1 if t1 > 0 else np.zeros_like(c1)
                    p2 = c2 / t2 if t2 > 0 else np.zeros_like(c2)
                    for ti, ci1, ci2, pi1, pi2 in zip(tx_sub, c1, c2, p1, p2):
                        rows.append({
                            "gene_id": g,
                            "group_1": k1,
                            "group_2": k2,
                            "transcript_id": ti,
                            "count_group1": float(ci1),
                            "count_group2": float(ci2),
                            "prop_group1": float(pi1),
                            "prop_group2": float(pi2),
                            "delta_prop": float(pi1 - pi2),
                        })
                tm_pb = pd.DataFrame(rows)
                df = df.merge(tm_pb, on=["gene_id", "group_1", "group_2"], how="left")
            else:
                # psi_mode == "cell"
                tm = self.transcript_metrics
                filt = tm["gene_id"].isin(df["gene_id"])
                df = df.merge(
                    tm.loc[filt],
                    on=["gene_id", "group_1", "group_2"],
                    how="left"
                )
                if not drop_unmatched_metrics:
                    df = df.merge(
                        tm.loc[filt].rename(columns={"group_1": "group_2", "group_2": "group_1"}),
                        on=["gene_id", "group_1", "group_2"],
                        how="left",
                        suffixes=("", "_alt")
                    )

        return df.reset_index(drop=True)


# %% ../nbs/004_switch_search.ipynb #485f1144
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.ticker import MaxNLocator
from pathlib import Path
import warnings
from typing import Dict, Optional

warnings.filterwarnings("ignore", message="findfont: .*", module="matplotlib")


# ───────────────────────────────────────────────────────────────────────
# Internal helpers
# ───────────────────────────────────────────────────────────────────────
def _neglog10(p):
    return -np.log10(np.clip(np.asarray(p, float), 1e-300, 1.0))


def _prep_volcano_df(df, effect_col="delta_pi", pval_col="adj_pval"):
    """Coerce numeric, drop non-finite rows, compute −log10(p)."""
    d = df.copy()
    d[effect_col] = pd.to_numeric(d[effect_col], errors="coerce")
    d[pval_col] = pd.to_numeric(d[pval_col], errors="coerce")
    d = d.replace([np.inf, -np.inf], np.nan).dropna(subset=[effect_col, pval_col])
    if d.empty:
        return d
    d["neglog10"] = _neglog10(d[pval_col].values)
    d = d.replace([np.inf, -np.inf], np.nan).dropna(subset=["neglog10"])
    return d


def _global_xlim(df_all, effect_col="delta_pi", pad=1.08, min_x=0.15):
    d = _prep_volcano_df(df_all, effect_col=effect_col)
    if d.empty:
        return (-min_x, min_x)
    xmax = float(np.nanmax(np.abs(d[effect_col].values)))
    xmax = max(min_x, xmax) * pad
    return (-xmax, xmax)


def _panel_ylim(d, *, y_pad=1.06, min_y=6.0, cap_q=0.995):
    if d.empty:
        return (0, min_y)
    y = d["neglog10"].values
    if cap_q is not None:
        y = np.clip(y, 0, float(np.quantile(y, cap_q)))
    ymax = max(min_y, float(np.nanmax(y))) * y_pad
    return (0, ymax)


def _select_label_rows(d, sig_mask, gene_col, effect_col, pval_col, top_n):
    """One row per gene, ranked by |effect|, drawn from plotted data only."""
    if d.empty:
        return d.iloc[0:0]
    s = d.loc[sig_mask].copy()
    if s.empty:
        return s
    s["abs_eff"] = s[effect_col].abs()
    s = s.sort_values([pval_col, "abs_eff"], ascending=[True, False])
    s = s.groupby(gene_col, as_index=False).first()
    s = s.sort_values("abs_eff", ascending=False).head(top_n)
    return s


def _n_switches(d, sig_mask, gene_col):
    """Count unique significant genes (= number of switches)."""
    if d.empty or not sig_mask.any():
        return 0
    return int(d.loc[sig_mask, gene_col].nunique())


_LABEL_BBOX = dict(boxstyle="round,pad=0.15", facecolor="white",
                   edgecolor="none", alpha=0.75)


# ───────────────────────────────────────────────────────────────────────
# draw_volcano_panel — one axes, one comparison
# ───────────────────────────────────────────────────────────────────────
def draw_volcano_panel(
    ax,
    df_comp,
    *,
    effect_col="delta_pi",
    pval_col="adj_pval",
    gene_col="gene_id",
    fdr_cutoff=0.05,
    eff_cutoff=0.10,
    top_n=6,
    xlim=None,
    ylim=None,
    cap_q=0.995,
    title=None,
    abbrev: Optional[Dict[str, str]] = None,
    show_n=True,
    label_cutoffs=False,
    # aesthetics
    s_bg=12,
    s_sig=25,
    alpha_bg=0.22,
    alpha_sig=0.85,
    color_bg=None,
    color_sig=None,
    font_size=7,
    rasterized=True,
    repel=True,
):
    """Draw a delta-pi vs FDR volcano into *ax*.

    Parameters
    ----------
    ax : matplotlib.axes.Axes
        Target axes.
    df_comp : DataFrame
        Results for ONE (group_1, group_2) comparison.
    effect_col : str
        Column with effect sizes (default ``"delta_pi"``).
    pval_col : str
        Column with adjusted p-values.
    gene_col : str
        Column with gene identifiers for labelling.
    fdr_cutoff, eff_cutoff : float
        Threshold lines.
    top_n : int
        Number of gene labels to show.
    xlim, ylim : tuple, optional
        Override axis limits.
    cap_q : float or None
        Quantile cap for y-axis.
    title : str, optional
        Panel title; defaults to "group_1 vs group_2".
    abbrev : dict, optional
        Mapping from full group names to abbreviated labels for the title.
    show_n : bool
        Annotate the number of significant switches in the corner.
    label_cutoffs : bool
        Annotate the threshold lines with their values.
    s_bg, s_sig : float
        Marker sizes (pt**2) for background / significant points.
    alpha_bg, alpha_sig : float
        Marker alpha.
    color_bg, color_sig : color, optional
        Override default matplotlib cycle colours.
    font_size : int
        Base font size.
    rasterized : bool
        Rasterise background scatter for lighter vector output.
    repel : bool
        Use adjustText for label placement when available.
    """
    d = _prep_volcano_df(df_comp, effect_col=effect_col, pval_col=pval_col)
    if d.empty:
        ax.axis("off")
        return

    sig = (d[pval_col] <= fdr_cutoff) & (d[effect_col].abs() >= eff_cutoff)
    n_sw = _n_switches(d, sig, gene_col)

    # ── limits ──
    if xlim is not None:
        ax.set_xlim(*xlim)
    else:
        xmax = max(0.20, float(np.nanmax(np.abs(d[effect_col].values)))) * 1.10
        ax.set_xlim(-xmax, xmax)

    if ylim is None:
        ylim = _panel_ylim(d, cap_q=cap_q)
    ax.set_ylim(*ylim)

    # ── scatter ──
    bg_kw = dict(s=s_bg, alpha=alpha_bg, linewidths=0, zorder=1,
                 rasterized=rasterized, clip_on=True)
    sig_kw = dict(s=s_sig, alpha=alpha_sig, linewidths=0, zorder=2, clip_on=True)
    if color_bg is not None:
        bg_kw["color"] = color_bg
    if color_sig is not None:
        sig_kw["color"] = color_sig

    ax.scatter(d.loc[~sig, effect_col], d.loc[~sig, "neglog10"],
               label="not significant", **bg_kw)
    ax.scatter(d.loc[sig, effect_col], d.loc[sig, "neglog10"],
               label="significant", **sig_kw)

    # ── threshold lines ──
    fdr_y = float(_neglog10(fdr_cutoff))
    ax.axhline(fdr_y, ls="--", lw=0.8, color="0.55", zorder=0)
    ax.axvline(+eff_cutoff, ls="--", lw=0.8, color="0.55", zorder=0)
    ax.axvline(-eff_cutoff, ls="--", lw=0.8, color="0.55", zorder=0)

    # ── cutoff labels (opt-in) ──
    if label_cutoffs:
        x0, x1 = ax.get_xlim()
        y0, y1 = ax.get_ylim()
        ax.text(x0 + 0.02 * (x1 - x0), fdr_y + 0.02 * (y1 - y0),
                f"FDR = {fdr_cutoff}", ha="left", va="bottom",
                fontsize=font_size - 1.5, color="0.4", style="italic",
                bbox=_LABEL_BBOX, zorder=5)
        ax.text(eff_cutoff + 0.015 * (x1 - x0), y0 + 0.04 * (y1 - y0),
                f"|Δπ| = {eff_cutoff}", ha="left", va="bottom",
                fontsize=font_size - 1.5, color="0.4", style="italic",
                bbox=_LABEL_BBOX, zorder=5)

    # ── gene labels ──
    lab = _select_label_rows(d, sig, gene_col, effect_col, pval_col, top_n)
    texts = []
    for _, r in lab.iterrows():
        t = ax.text(
            float(r[effect_col]),
            float(r["neglog10"]) + 0.15,
            str(r[gene_col]),
            fontsize=font_size,
            ha="center", va="bottom",
            clip_on=True, zorder=6,
            bbox=_LABEL_BBOX,
        )
        texts.append(t)

    if repel and texts:
        try:
            from adjustText import adjust_text
            adjust_text(
                texts, ax=ax,
                expand_points=(1.15, 1.3),
                expand_text=(1.1, 1.2),
                arrowprops=dict(arrowstyle="-", lw=0.4, color="0.5", alpha=0.7),
            )
        except ModuleNotFoundError:
            y_used = []
            for t in texts:
                x, y = t.get_position()
                while any(abs(y - yy) < 1.0 for yy in y_used):
                    y += 1.0
                t.set_position((x, y))
                y_used.append(y)

    # clamp labels inside axes
    x0, x1 = ax.get_xlim()
    y0, y1 = ax.get_ylim()
    for t in texts:
        x, y = t.get_position()
        t.set_position((
            float(np.clip(x, x0 + 0.03 * (x1 - x0), x1 - 0.03 * (x1 - x0))),
            float(np.clip(y, y0 + 0.03 * (y1 - y0), y1 - 0.06 * (y1 - y0))),
        ))

    # ── cosmetics ──
    ax.set_xlabel("Δπ", fontsize=font_size + 1)
    ax.set_ylabel("−log10(FDR)", fontsize=font_size + 1)
    ax.tick_params(labelsize=font_size)
    ax.yaxis.set_major_locator(MaxNLocator(integer=True))
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)

    # ── title ──
    _abbrev = abbrev or {}
    if title is not None:
        ax.set_title(title, fontsize=font_size + 2, pad=4, linespacing=1.3)
    elif "group_1" in d.columns and "group_2" in d.columns:
        g1, g2 = d["group_1"].iat[0], d["group_2"].iat[0]
        lab1 = _abbrev.get(g1, g1)
        lab2 = _abbrev.get(g2, g2)
        ax.set_title(f"{lab1} vs\n{lab2}", fontsize=font_size + 2,
                     pad=4, linespacing=1.3)

    # ── n_switches ──
    if show_n:
        ax.text(
            0.97, 0.03, f"n={n_sw}",
            transform=ax.transAxes,
            fontsize=font_size,
            fontweight="medium",
            ha="right", va="bottom", color="0.3",
            bbox=dict(boxstyle="round,pad=0.2", facecolor="white",
                      edgecolor="0.7", alpha=0.85, linewidth=0.5),
            zorder=7,
        )


# ───────────────────────────────────────────────────────────────────────
# volcano_grid — all comparisons on one figure
# ───────────────────────────────────────────────────────────────────────
def volcano_grid(
    df_all,
    *,
    n_cols=3,
    figsize_per_panel=3.2,
    save=None,
    show=True,
    share_x=True,
    cap_q=0.995,
    dpi=300,
    abbrev: Optional[Dict[str, str]] = None,
    legend=True,
    **panel_kw,
):
    """Tile every (group_1, group_2) comparison into a grid of volcano panels.

    Parameters
    ----------
    df_all : DataFrame
        Full results table with ``group_1`` and ``group_2`` columns.
    n_cols : int
        Columns in the grid.
    figsize_per_panel : float
        Size of each panel in inches.
    save : str or Path, optional
        Save path (PDF/SVG/PNG).
    show : bool
        Call ``plt.show()``.
    share_x : bool
        Use a global x-axis across all panels.
    cap_q : float or None
        Per-panel y-axis quantile cap.
    dpi : int
        Figure resolution.
    abbrev : dict, optional
        Mapping from full group names to abbreviated title labels.
    legend : bool
        Show a shared legend below the grid.
    **panel_kw
        Forwarded to :func:`draw_volcano_panel`.
    """
    effect_col = panel_kw.get("effect_col", "delta_pi")
    comps = list(df_all.groupby(["group_1", "group_2"]))
    if not comps:
        raise ValueError("No (group_1, group_2) comparisons found.")

    n = len(comps)
    n_rows = int(np.ceil(n / n_cols))

    fig, axes = plt.subplots(
        n_rows, n_cols,
        figsize=(n_cols * figsize_per_panel, n_rows * figsize_per_panel),
        dpi=dpi,
        squeeze=False,
        constrained_layout=True,
    )

    xlim = _global_xlim(df_all, effect_col=effect_col) if share_x else None

    ax_iter = axes.flatten()
    for i, ((g1, g2), sub) in enumerate(comps):
        draw_volcano_panel(
            ax_iter[i], sub,
            xlim=xlim, cap_q=cap_q, abbrev=abbrev,
            **panel_kw,
        )

    for ax in ax_iter[n:]:
        ax.axis("off")

    if legend and n > 0:
        handles, labels = ax_iter[0].get_legend_handles_labels()
        if handles:
            fig.legend(
                handles, labels,
                loc="lower center",
                ncol=len(handles),
                fontsize=panel_kw.get("font_size", 7),
                frameon=False,
                bbox_to_anchor=(0.5, -0.02),
            )

    if save:
        save = Path(save)
        save.parent.mkdir(parents=True, exist_ok=True)
        fig.savefig(save, bbox_inches="tight", dpi=dpi)

    if show:
        plt.show(block=False)
    else:
        plt.close(fig)

    return fig

# %% ../nbs/004_switch_search.ipynb #ced0b79c
def filter_sample_replicated_transcripts(adata, sample_col='sample', min_samples=2, min_umi=1):
    """
    Filters out transcripts that are not detected above a minimum UMI threshold 
    in at least a specified number of samples (replicates).

    Parameters:
      adata: AnnData object containing transcript-level counts.
      sample_col: Column in adata.obs that identifies the replicate/sample.
      min_samples: Minimum number of samples in which the transcript must be expressed.
      min_umi: Minimum UMI count in a sample for the transcript to be considered "expressed".
    
    Returns:
      A new AnnData object containing only transcripts that replicate across samples.
    """
    # Get unique sample identifiers.
    samples = adata.obs[sample_col].unique()
    
    # Dictionary to count in how many samples each transcript is expressed.
    transcript_presence = {tx: 0 for tx in adata.var_names}
    
    # Loop through each sample, calculate transcript counts, and mark transcripts that pass the threshold.
    for sample in samples:
        sample_adata = adata[adata.obs[sample_col] == sample]
        # Use your safe_sum helper to support both sparse and dense matrices.
        counts = safe_sum(sample_adata.X)
        # Loop over transcripts: if count > min_umi, mark as present.
        for tx, count in zip(adata.var_names, counts):
            if count > min_umi:
                transcript_presence[tx] += 1
    
    # Select transcripts that are expressed in at least min_samples samples.
    transcripts_to_keep = [tx for tx, count in transcript_presence.items() if count >= min_samples]
    print(f"Filtering out {adata.n_vars - len(transcripts_to_keep)} transcripts that are sample-specific")
    
    # Return a new AnnData object with only the replicated transcripts.
    return adata[:, transcripts_to_keep].copy()





# %% ../nbs/004_switch_search.ipynb #5e7513e7
import pandas as pd
from scipy.stats import spearmanr

def compute_as_similarity(
    adata: ad.AnnData,
    group_column: str,
    transcripts: list[str],
    epsilon: float = 1e-6,
) -> pd.DataFrame:
    """
    Compute an AS‐similarity matrix (Spearman ρ) between all levels of `group_column`,
    using the PSI values of `transcripts`.

    Parameters
    ----------
    adata
        An AnnData containing your transcript‐by‐cell counts.
    group_column
        Column in adata.obs defining your cell groups (e.g. “cell_type”).
    transcripts
        List of var_names (transcript IDs) to include in the calculation.
    epsilon
        Small pseudocount to avoid division by zero when computing PSI.

    Returns
    -------
    corr_df : DataFrame
        A square DataFrame indexed and columned by the unique values of `group_column`,
        where corr_df.loc[g1, g2] is the Spearman ρ between the average‐PSI vectors
        of group g1 and group g2.
    """
    # 1) get cell‐level PSI matrix: cells × transcripts
    psi_mat = compute_cell_level_psi(adata, transcripts, epsilon)  
    psi_df = pd.DataFrame(psi_mat, 
                          index=adata.obs_names, 
                          columns=transcripts)

    # 2) tack on the group label, then average PSI per group
    psi_df[group_column] = adata.obs[group_column].values
    group_avg = psi_df.groupby(group_column).mean()

    # 3) compute pairwise Spearman correlations between group‐average PSI vectors
    groups = group_avg.index
    corr = pd.DataFrame(index=groups, columns=groups, dtype=float)
    for g1 in groups:
        for g2 in groups:
            ρ, _ = spearmanr(group_avg.loc[g1], group_avg.loc[g2])
            corr.loc[g1, g2] = ρ

    return corr


# %% ../nbs/004_switch_search.ipynb #b12f654a
def get_top_n_isoforms(adata, gene_id, top_n=5, strip=False):
    """
    Get the top_n transcript IDs for a given gene based on overall average expression.

    Parameters:
    - adata: AnnData object containing transcript-level data.
    - gene_id: The gene ID to search for corresponding isoforms.
    - top_n: The number of top isoforms to return based on overall average expression.
    - strip: Boolean indicating whether to strip the dot and everything after from the ID.

    Returns:
    - A list of top_n transcript IDs.
    """
    # Identify isoforms for the given gene ID
    isoforms = adata.var[adata.var['geneId'] == gene_id].index
    if len(isoforms) == 0:
        print(f"No isoforms found for gene ID: {gene_id}")
        return []

    # Calculate the overall average expression for each isoform
    overall_expr = adata.to_df()[isoforms].mean()

    # Get the top_n isoforms by average expression
    top_isoforms = overall_expr.sort_values(ascending=False).head(top_n).index.tolist()

    # Strip the dot and everything after from the ID if strip is True
    if strip:
        top_isoforms = [isoform.split('.')[0] for isoform in top_isoforms]

    return top_isoforms

