import matplotlib.pyplot as plt
import numpy as np

def plot_as_similarity(sim, cmap='magma'):
    """
    Enhanced AS‐similarity heatmap with colorbar and a 'magma' colormap.
    Text labels switch to white/black for better contrast.
    """
    fig, ax = plt.subplots(figsize=(8, 8))
    cax = ax.matshow(sim.values, cmap=cmap)
    # add colorbar with label
    cb = fig.colorbar(cax, ax=ax, fraction=0.046, pad=0.04)
    cb.set_label("Spearman ρ", rotation=270, labelpad=15)

    labels = sim.index.tolist()
    ax.set_xticks(np.arange(len(labels)))
    ax.set_yticks(np.arange(len(labels)))
    ax.set_xticklabels(labels, rotation=90, fontsize=10)
    ax.set_yticklabels(labels, fontsize=10)

    # annotate with correlation values and switch text color for visibility
    for (i, j), val in np.ndenumerate(sim.values):
        color = 'white' if val < 0.5 else 'black'
        ax.text(j, i, f"{val:.2f}", ha='center', va='center', color=color, fontsize=8)

    ax.set_title("AS Similarity (Spearman ρ)", pad=20)
    plt.tight_layout()
    plt.show()


