import itertools
import os
import warnings

import numpy as np
import pandas as pd
from joblib import Parallel, delayed
from scipy.sparse import issparse
from statsmodels.stats.multitest import multipletests

from edgepython.dgelist import DGEList
from edgepython.normalization import calc_norm_factors
from edgepython.dispersion import estimate_disp
from edgepython.glm_fit import glm_ql_fit
from edgepython.splicing import diff_splice


def _psi_from_pseudobulk(cnts, gene_ids, g1_mask, epsilon=1e-6):
    """
    Vectorized PSI from pseudobulk count matrix.
    cnts    : (n_tx, n_samples) float64
    g1_mask : (n_samples,) bool — True for group-1 samples
    Returns (psi1, psi2) each shape (n_tx,).
    """
    c1 = cnts[:, g1_mask].sum(axis=1).astype(np.float64)
    c2 = cnts[:, ~g1_mask].sum(axis=1).astype(np.float64)
    _, inv = np.unique(gene_ids, return_inverse=True)
    g1_tot = np.bincount(inv, weights=c1)[inv] + epsilon
    g2_tot = np.bincount(inv, weights=c2)[inv] + epsilon
    return c1 / g1_tot, c2 / g2_tot


def pseudobulk_diff_splice(
    adata,
    *,
    primary_col: str = "cell_type",
    secondary_col: str | None = None,
    within: str = "primary",          # "primary", "secondary", or "all"
    group_col: str | None = None,     # deprecated alias for primary_col
    replicate_col: str = "batch",
    layer: str | None = None,
    gene_col: str = "geneId",
    comparisons=None,
    group_vs_rest: bool = False,
    # sample filters
    min_cells: int = 10,
    # transcript abundance filters
    min_reads: int = 10,
    min_transcript_counts: int | None = None,  # deprecated alias for min_reads
    min_isoform_fraction: float = 0.01,
    min_samples_expressed: int = 1,
    min_isoforms_gene: int = 2,
    # covariates
    covariates=None,
    # output
    output_level: str = "gene",
    fdr: float = 0.05,
    return_all: bool = False,
    prior_count: float = 0.125,
    verbose: bool = True,
    n_jobs: int = -1,
) -> pd.DataFrame:
    """
    Pseudobulk differential splicing using edgePython's diff_splice (QL F-test).

    Counts are summed per (primary_col, replicate_col), a quasi-likelihood GLM is
    fitted per comparison pair, and diff_splice tests whether each gene shows
    differential isoform usage beyond its overall expression change.

    Parameters
    ----------
    primary_col            : obs column defining the primary grouping variable
    secondary_col          : optional obs column for nested designs
    within                 : with secondary_col — which axis to compare within:
                             "primary" (default), "secondary", or "all"
    replicate_col          : obs column defining biological replicates
    layer                  : layer with raw counts; None uses .X
    gene_col               : var column mapping transcripts to genes
    comparisons            : explicit list of (g1, g2); None = all pairwise
    group_vs_rest          : test each group vs all others
    min_cells              : min cells per pseudobulk sample
    min_reads              : min total pseudobulk counts per transcript
    min_isoform_fraction   : min fraction of gene total per transcript
    min_samples_expressed  : min pseudobulk samples with >0 counts
    min_isoforms_gene      : min isoforms per gene after filtering (default 2)
    covariates             : obs column name(s) for GLM covariates
    output_level           : "gene" or "transcript"
    fdr                    : BH adj. p-value threshold
    return_all             : return all results without FDR filtering
    prior_count            : GLM prior count for offset shrinkage
    verbose                : print filtering summary
    n_jobs                 : parallel workers (-1 = all CPUs)

    Returns
    -------
    Gene-level:
        gene_id, group_1, group_2, n_transcripts, n_cells_group1, n_cells_group2,
        delta_pi, stat, p_value, simes_p_value, adj_pval

    Transcript-level (output_level="transcript"):
        adds transcript_id, transcript_stat, transcript_p_value, log_fc,
        avg_psi_group1, avg_psi_group2, delta_psi,
        gene_stat, gene_p_value, gene_simes_p_value
    """
    # -- deprecated aliases --------------------------------------------------
    if group_col is not None:
        warnings.warn(
            "group_col is deprecated; use primary_col instead.",
            DeprecationWarning, stacklevel=2,
        )
        primary_col = group_col
    if min_transcript_counts is not None:
        warnings.warn(
            "min_transcript_counts is deprecated; use min_reads instead.",
            DeprecationWarning, stacklevel=2,
        )
        min_reads = min_transcript_counts

    if output_level not in {"gene", "transcript"}:
        raise ValueError("output_level must be 'gene' or 'transcript'.")
    if within not in {"primary", "secondary", "all"}:
        raise ValueError("within must be 'primary', 'secondary', or 'all'.")

    n_jobs = os.cpu_count() if n_jobs in (-1, 0) else n_jobs

    # -- 1. Extract counts ---------------------------------------------------
    X = adata.layers[layer] if layer is not None else adata.X
    if issparse(X):
        X = X.toarray()
    X = np.asarray(X, dtype=np.float64)

    if gene_col not in adata.var.columns:
        raise ValueError(f"'{gene_col}' not found in adata.var.columns")

    gene_ids = adata.var[gene_col].values.copy()
    tx_ids   = adata.var.index.values.copy()
    cov_cols = (
        [covariates] if isinstance(covariates, str) else list(covariates)
    ) if covariates is not None else []

    # -- 2. Composite group key ----------------------------------------------
    obs = adata.obs[[primary_col, replicate_col] + cov_cols].copy()
    if secondary_col is not None:
        obs["_grp"] = (
            obs[primary_col].astype(str) + SEP + adata.obs[secondary_col].astype(str)
        )
    else:
        obs["_grp"] = obs[primary_col].astype(str)
    obs["_key"] = obs["_grp"] + "||" + obs[replicate_col].astype(str)

    # -- 3. Vectorized pseudobulk aggregation --------------------------------
    pb_keys = obs["_key"].unique()
    pb_idx  = obs["_key"].map({k: j for j, k in enumerate(pb_keys)}).values

    # build (n_cells, n_pb) indicator, then pb_counts = X.T @ W
    W = np.zeros((len(obs), len(pb_keys)), dtype=np.float64)
    W[np.arange(len(obs)), pb_idx] = 1.0
    pb_counts = X.T @ W   # (n_tx, n_pb)

    pb_meta_rows = []
    for key in pb_keys:
        mask = obs["_key"].values == key
        grp  = obs.loc[mask, "_grp"].iloc[0]
        rep  = obs.loc[mask, replicate_col].iloc[0]
        row  = {"_grp": grp, replicate_col: rep, "_n_cells": int(mask.sum())}
        for col in cov_cols:
            vals = adata.obs.loc[mask, col]
            if vals.nunique() > 1:
                warnings.warn(
                    f"Covariate '{col}' is not constant within pseudobulk sample "
                    f"'{key}'; using first value."
                )
            row[col] = vals.iloc[0]
        pb_meta_rows.append(row)

    pb_meta = pd.DataFrame(pb_meta_rows, index=pb_keys)

    # drop underpowered pseudobulk samples
    keep_s    = pb_meta["_n_cells"] >= min_cells
    pb_counts = pb_counts[:, keep_s.values]
    pb_meta   = pb_meta[keep_s].copy()

    # -- 4. Transcript abundance filters -------------------------------------
    tx_totals  = pb_counts.sum(axis=1)
    keep_tx    = tx_totals >= min_reads

    if min_samples_expressed > 0:
        keep_tx &= (pb_counts > 0).sum(axis=1) >= min_samples_expressed

    if min_isoform_fraction > 0:
        _, inv    = np.unique(gene_ids, return_inverse=True)
        gene_tots = np.bincount(inv, weights=tx_totals)[inv]
        fracs     = np.where(gene_tots > 0, tx_totals / gene_tots, 0.0)
        keep_tx  &= fracs >= min_isoform_fraction

    pb_counts = pb_counts[keep_tx]
    gene_ids  = gene_ids[keep_tx]
    tx_ids    = tx_ids[keep_tx]

    if min_isoforms_gene > 1:
        _, inv        = np.unique(gene_ids, return_inverse=True)
        iso_per_gene  = np.bincount(inv)
        keep_gene     = iso_per_gene[inv] >= min_isoforms_gene
        pb_counts     = pb_counts[keep_gene]
        gene_ids      = gene_ids[keep_gene]
        tx_ids        = tx_ids[keep_gene]

    if verbose:
        n_before = int(keep_tx.sum()) if not (min_isoforms_gene > 1) else int(keep_tx.sum())
        print(
            f"Transcripts after filtering: {len(tx_ids)} / {len(adata.var)}"
            f"  ({len(np.unique(gene_ids))} genes)"
        )

    genes_df = pd.DataFrame({"GeneID": gene_ids, "TranscriptID": tx_ids})

    # -- 5. Comparison pairs -------------------------------------------------
    all_grps = sorted(pb_meta["_grp"].unique().tolist())

    if group_vs_rest:
        pairs = [(g, "rest") for g in all_grps]
    elif comparisons is not None:
        pairs = list(comparisons)
    elif secondary_col is None:
        pairs = list(itertools.combinations(all_grps, 2))
    else:
        if within == "primary":
            pairs = []
            for p in obs[primary_col].unique():
                ks = [k for k in all_grps if k.split(SEP)[0] == str(p)]
                pairs.extend(itertools.combinations(sorted(ks), 2))
        elif within == "secondary":
            pairs = []
            for s in adata.obs[secondary_col].unique():
                ks = [k for k in all_grps if k.split(SEP)[1] == str(s)]
                pairs.extend(itertools.combinations(sorted(ks), 2))
        else:  # "all"
            pairs = list(itertools.combinations(all_grps, 2))

    # -- 6. Per-pair worker --------------------------------------------------
    def _run_pair(g1, g2):
        if g2 == "rest":
            sel     = np.ones(len(pb_meta), dtype=bool)
            g1_mask = (pb_meta["_grp"] == g1).values
        else:
            sel     = pb_meta["_grp"].isin([g1, g2]).values
            g1_mask = (pb_meta.loc[sel, "_grp"] == g1).values

        cnts   = pb_counts[:, sel]
        meta   = pb_meta[sel]
        n_samp = cnts.shape[1]

        if n_samp < 2:
            warnings.warn(f"Skipping {g1} vs {g2}: fewer than 2 pseudobulk samples.")
            return None

        n_cells_g1 = int(meta.loc[meta["_grp"] == g1, "_n_cells"].sum())
        n_cells_g2 = int(meta.loc[meta["_grp"] != g1, "_n_cells"].sum())

        lib_sizes  = cnts.sum(axis=0)
        grp_ind    = g1_mask.astype(float)

        samples_df = pd.DataFrame({
            "group":        meta["_grp"].values,
            "replicate":    meta[replicate_col].values,
            "lib.size":     lib_sizes,
            "norm.factors": 1.0,
        }, index=meta.index)

        design_cols = [np.ones(n_samp)]
        for col in cov_cols:
            design_cols.append(
                pd.to_numeric(meta[col], errors="coerce").fillna(0).values
            )
        design_cols.append(grp_ind)
        design   = np.column_stack(design_cols)
        coef_idx = design.shape[1] - 1

        try:
            y      = DGEList(counts=cnts, samples=samples_df, genes=genes_df)
            y      = calc_norm_factors(y)
            y_disp = estimate_disp(y, design=design)
            fit    = glm_ql_fit(y_disp, design=design)
            res    = diff_splice(fit, coef=coef_idx, geneid=gene_ids, verbose=False)
        except Exception as e:
            warnings.warn(f"diff_splice failed for {g1} vs {g2}: {e}")
            return None

        stat_col = "gene.F" if "gene.F" in res else "gene.LR"

        # -- delta_pi from pseudobulk proportions ----------------------------
        psi1, psi2 = _psi_from_pseudobulk(cnts, gene_ids, g1_mask)
        dpsi_df    = pd.DataFrame({
            "gene_id":    gene_ids,
            "delta_psi":  psi1 - psi2,
        })
        dpi_map = (
            dpsi_df.groupby("gene_id")["delta_psi"]
                   .apply(delta_pi_one_gene_signed)
        )

        # -- gene-level table ------------------------------------------------
        gene_tbl = res["gene.genes"].copy()
        gene_tbl = gene_tbl.rename(columns={"GeneID": "gene_id", "NExons": "n_transcripts"})
        gene_tbl["group_1"]        = g1
        gene_tbl["group_2"]        = g2
        gene_tbl["n_cells_group1"] = n_cells_g1
        gene_tbl["n_cells_group2"] = n_cells_g2
        gene_tbl["delta_pi"]       = gene_tbl["gene_id"].map(dpi_map)
        gene_tbl["stat"]           = res[stat_col]
        gene_tbl["p_value"]        = res["gene.p.value"]
        gene_tbl["simes_p_value"]  = res["gene.Simes.p.value"]

        if output_level == "gene":
            return gene_tbl

        # -- transcript-level table ------------------------------------------
        tx_tbl = res["genes"].copy()
        tx_tbl = tx_tbl.rename(columns={
            "GeneID":       "gene_id",
            "TranscriptID": "transcript_id",
        })
        tx_tbl["group_1"]            = g1
        tx_tbl["group_2"]            = g2
        tx_stat_col                  = "exon.F" if "exon.F" in res else "exon.LR"
        tx_tbl["transcript_stat"]    = res[tx_stat_col]
        tx_tbl["transcript_p_value"] = res["exon.p.value"]
        tx_tbl["log_fc"]             = res["coefficients"]

        tx_pos       = pd.Series(np.arange(len(tx_ids)), index=tx_ids)
        pos          = tx_tbl["transcript_id"].map(tx_pos).values
        p1, p2       = _psi_from_pseudobulk(cnts[pos], gene_ids[pos], g1_mask)
        tx_tbl["avg_psi_group1"] = p1
        tx_tbl["avg_psi_group2"] = p2
        tx_tbl["delta_psi"]      = p1 - p2

        gene_lk = gene_tbl.set_index("gene_id")[[
            "stat", "p_value", "simes_p_value",
            "delta_pi", "n_cells_group1", "n_cells_group2",
        ]].rename(columns={"stat": "gene_stat", "p_value": "gene_p_value",
                            "simes_p_value": "gene_simes_p_value"})
        tx_tbl = tx_tbl.merge(gene_lk, on="gene_id", how="left")

        return tx_tbl

    # -- 7. Run pairs --------------------------------------------------------
    raw     = Parallel(n_jobs=n_jobs, prefer="processes")(
        delayed(_run_pair)(g1, g2) for g1, g2 in pairs
    )
    results = [r for r in raw if r is not None]

    if not results:
        return pd.DataFrame()

    out = pd.concat(results, ignore_index=True)

    # -- 8. Multiple testing -------------------------------------------------
    pval_col        = "p_value" if output_level == "gene" else "transcript_p_value"
    out["adj_pval"] = multipletests(out[pval_col], method="fdr_bh")[1]

    if not return_all:
        out = out[out["adj_pval"] <= fdr].copy()

    return out.sort_values("adj_pval").reset_index(drop=True)

